from collections import deque

def shortest_path(graph, start, goal):
    queue = deque([start])
    parent = {start: None}
    while queue:
        node = queue.popleft()
        if node == goal:
            path = []
            while node is not None:
                path.append(node)
                node = parent[node]
            return path[::-1]
        for neighbor in graph.get(node, ()):
            if neighbor not in parent:
                parent[neighbor] = node
                queue.append(neighbor)
    return None

# Nodes are visited at most once, including cycles and self-edges.
assert shortest_path({1: [2], 2: [1, 3]}, 1, 3) == [1, 2, 3]
assert shortest_path({}, 1, 1) == [1]
assert shortest_path({1: [2]}, 1, 3) is None

type Result<T> = { ok: true; value: T } | { ok: false; error: string };

async function readJson(url: string, signal?: AbortSignal): Promise<Result<unknown>> {
  try {
    const response = await fetch(url, { signal });
    if (!response.ok) {
      return { ok: false, error: `HTTP ${response.status}` };
    }
    const value: unknown = await response.json();
    return { ok: true, value };
  } catch (error) {
    return { ok: false, error: error instanceof Error ? error.message : String(error) };
  }
}

function isConfig(value: unknown): value is { port: number; host: string } {
  if (typeof value !== 'object' || value === null) return false;
  const v = value as Record<string, unknown>;
  return Number.isInteger(v.port) && typeof v.host === 'string';
}
